// Push and Notification Handlers for MOMO Mobile PWA
self.addEventListener('push', function(event) {
  var data = {
    title: 'MOMO Fleet Notification',
    body: 'New alert received',
    color: 'orange',
    type: 'ALERT'
  };
  try {
    if (event.data) {
      data = event.data.json();
    }
  } catch (e) {
    if (event.data) {
      data.body = event.data.text();
    }
  }

  var icon = '/android-chrome-192x192.png';
  if (data.color === 'green') {
    icon = '/paidoutlay.png';
  } else if (data.color === 'red') {
    icon = '/violation.png';
  }

  var title = (data.notification && data.notification.title) || data.title || (data.data && data.data.title) || 'MOMO Fleet Alert';
  var body = (data.notification && data.notification.body) || data.body || (data.data && data.data.body) || 'New alert received';

  var options = {
    body: body,
    icon: icon,
    badge: '/favicon-32x32.png',
    tag: data.type || 'momo-alert',
    vibrate: [250, 100, 250, 100, 400],
    renotify: true,
    requireInteraction: true,
    data: { url: (data.data && data.data.url) || data.url || '/' }
  };

  if ('setAppBadge' in navigator) {
    var unread = Number(data.badgeCount || (data.data && data.data.badgeCount)) || 1;
    navigator.setAppBadge(unread).catch(function() {});
  }

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', function(event) {
  event.notification.close();

  if ('clearAppBadge' in navigator) {
    navigator.clearAppBadge().catch(function() {});
  }

  var targetUrl = (event.notification.data && event.notification.data.url) || '/';
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function(clientList) {
      for (var i = 0; i < clientList.length; i++) {
        var client = clientList[i];
        if (client.url.indexOf(self.location.origin) !== -1 && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) {
        return clients.openWindow(targetUrl);
      }
    })
  );
});